        PrintWriter writer = new PrintWriter(System.out);
        int n = Integer.parseInt(reader.readLine());
        String line = reader.readLine();
        char[] s = line.toCharArray();
        int[] count = new int[3];
        int[][] positions = new int[3][n];
        for (int i = 0; i < n; i++) {
            int type = s[i] == 'K' ? 0 : (s[i] == 'V' ? 1 : 2);
            positions[type][count[type]] = i;
            count[type]++;
        }
        int[][][][] dp = new int[2][count[0] + 1][count[1] + 1][count[2] + 1];
        for (int[][][] layer : dp) for (int[][] row : layer) for (int[] col : row) Arrays.fill(col, Integer.MAX_VALUE / 2);
        dp[0][0][0][0] = 0;
