                            for (int j = i2; j < count[2]; j++) if (positions[2][j] < p) swaps++;
                            dp[1][i0][i1 + 1][i2] = Math.min(dp[1][i0][i1 + 1][i2], current + swaps);
                        }
                        if (i2 < count[2]) {
                            int swaps = 0, p = positions[2][i2];
                            for (int j = i0; j < count[0]; j++) if (positions[0][j] < p) swaps++;
                            for (int j = i1; j < count[1]; j++) if (positions[1][j] < p) swaps++;
                            dp[0][i0][i1][i2 + 1] = Math.min(dp[0][i0][i1][i2 + 1], current + swaps);
                        }
